mapper.select:
SELECT d.id, d.user_id, d.bill_id, d.item_name, d.amount, d.sort_order FROM fly_bill_breakdown d JOIN fly_bill b ON b.id = d.bill_id WHERE d.user_id = #{userId} AND b.user_id = #{userId}
AND d.bill_id IN #{id}
AND 1 = 0
ORDER BY d.bill_id ASC, d.sort_order ASC, d.id ASC

